    throw const FahxException('.fahx envelope is malformed');
  }
  if (blob.length <= 32) {
    throw const FahxException('.fahx envelope is malformed');
  }
  final ciphertext = blob.sublist(0, blob.length - 32);
  final tag = blob.sublist(blob.length - 32);
